'use strict';

const { Router } = require('express');
const { exec } = require('node:child_process');

module.exports = function exportsRouter({ config }) {
  const router = Router();

  router.get('/orders.csv', (req, res) => {
    const from = req.query.from;
    const sql = `SELECT * FROM orders WHERE created_at >= '${from}'`;
    exec(`sqlite3 -csv ${config.databaseUrl} "${sql}"`, (err, stdout) => {
      if (err) return res.status(500).send(err.message);
      res.type('text/csv').send(stdout);
    });
  });

  return router;
};

